// @ts-nocheck
import React, { useState, useEffect, useRef } from "react"
import { motion } from "framer-motion"
import { addPropertyControls, ControlType, RenderTarget } from "framer"

/**
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 * @framerIntrinsicWidth 400
 * @framerIntrinsicHeight 300
 * @framerDisableUnlink
 */
export default function FlowReactor(props) {
    const {
        inputs,
        outputs,
        core,
        showDebug,
        leftAnimation,
        rightAnimation,
        coreAnimation,
    } = props

    const containerRef = useRef(null)
    const [containerDimensions, setContainerDimensions] = useState({
        width: 0,
        height: 0,
    })

    const hasInputs = inputs && inputs.length > 0
    const hasOutputs = outputs && outputs.length > 0
    const hasCore = !!core
    const isCanvas = RenderTarget.current() === RenderTarget.canvas

    useEffect(() => {
        if (containerRef.current && !isCanvas) {
            const updateSize = () => {
                setContainerDimensions({
                    width: containerRef.current.offsetWidth,
                    height: containerRef.current.offsetHeight,
                })
            }
            updateSize()
            window.addEventListener("resize", updateSize)
            return () => window.removeEventListener("resize", updateSize)
        }
    }, [isCanvas])

    const [inputParticles, setInputParticles] = useState([])
    const [outputParticles, setOutputParticles] = useState([])
    const [corePop, setCorePop] = useState(false)

    const centerX = containerDimensions.width / 2
    const centerY = containerDimensions.height / 2

    // Left → Core (emit cadence with random vertical spawn)
    useEffect(() => {
        if (isCanvas || !hasInputs || containerDimensions.width === 0) return
        let intervalId
        const start = () => {
            intervalId = setInterval(
                () => {
                    const randomIndex = Math.floor(
                        Math.random() * inputs.length
                    )
                    const h = containerDimensions.height || 0
                    const padding = 4
                    const y = Math.max(
                        padding,
                        Math.min(h - padding, Math.random() * h)
                    )
                    setInputParticles((prev) => [
                        ...prev,
                        { id: Math.random(), comp: inputs[randomIndex], y },
                    ])
                },
                Math.max(0.05, leftAnimation.delay) * 1000
            )
        }
        const t = setTimeout(
            start,
            Math.max(0, leftAnimation.initialDelay || 0) * 1000
        )
        return () => {
            clearTimeout(t)
            clearInterval(intervalId)
        }
    }, [
        inputs,
        hasInputs,
        containerDimensions.width,
        containerDimensions.height,
        isCanvas,
        leftAnimation.delay,
        leftAnimation.initialDelay,
    ])

    // Core → Right (emit cadence). Core pop synced to emission; pop duration controls appearance animation of right items
    useEffect(() => {
        if (isCanvas || !hasOutputs || containerDimensions.width === 0) return
        let intervalId
        const emit = () => {
            const randomIndex = Math.floor(Math.random() * outputs.length)
            setCorePop(true)
            setTimeout(
                () => setCorePop(false),
                Math.max(0.05, coreAnimation.duration) * 500
            )
            setOutputParticles((prev) => [
                ...prev,
                {
                    id: Math.random(),
                    comp: outputs[randomIndex],
                    coreDuration: coreAnimation.duration,
                },
            ])
        }
        const start = () => {
            emit()
            intervalId = setInterval(
                emit,
                Math.max(0.05, rightAnimation.delay) * 1000
            )
        }
        const t = setTimeout(
            start,
            Math.max(0, rightAnimation.initialDelay || 0) * 1000
        )
        return () => {
            clearTimeout(t)
            clearInterval(intervalId)
        }
    }, [
        outputs,
        hasOutputs,
        containerDimensions.width,
        isCanvas,
        rightAnimation.delay,
        rightAnimation.initialDelay,
        coreAnimation.duration,
    ])

    if (isCanvas) {
        return (
            <div
                ref={containerRef}
                style={{ width: "100%", height: "100%", position: "relative" }}
            >
                <div
                    style={{
                        position: "absolute",
                        left: "10%",
                        top: "50%",
                        transform: "translateY(-50%)",
                    }}
                >
                    {hasInputs ? inputs[0] : <EmptyState title="Left" />}
                </div>
                <div
                    style={{
                        position: "absolute",
                        left: "50%",
                        top: "50%",
                        transform: "translate(-50%, -50%)",
                    }}
                >
                    {hasCore ? core : <EmptyState title="Core" />}
                </div>
                <div
                    style={{
                        position: "absolute",
                        right: "10%",
                        top: "50%",
                        transform: "translateY(-50%)",
                    }}
                >
                    {hasOutputs ? outputs[0] : <EmptyState title="Right" />}
                </div>
            </div>
        )
    }

    return (
        <div
            ref={containerRef}
            style={{
                width: "100%",
                height: "100%",
                position: "relative",
                overflow: "visible",
            }}
        >
            {showDebug && (
                <div
                    style={{
                        position: "absolute",
                        top: 10,
                        left: 10,
                        background: "rgba(0,0,0,0.8)",
                        color: "white",
                        padding: 10,
                        fontSize: 11,
                        zIndex: 1000,
                        fontFamily: "monospace",
                        lineHeight: 1.5,
                    }}
                >
                    <div>
                        Container: {containerDimensions.width}x
                        {containerDimensions.height}
                    </div>
                    <div>
                        Center: ({centerX}, {centerY})
                    </div>
                    <div>Left particles: {inputParticles.length}</div>
                    <div>Right particles: {outputParticles.length}</div>
                </div>
            )}

            {/* Left Inputs: random vertical spawn → core center with entrance and exit staging */}
            {inputParticles.map((p) => {
                const D = Math.max(0.05, leftAnimation.speed)
                const E = Math.max(
                    0,
                    Math.min(leftAnimation.entranceDuration || 0, D)
                )
                const X = Math.max(
                    0,
                    Math.min(leftAnimation.exitDuration || 0, D)
                )
                const entranceEnd = D === 0 ? 0 : E / D
                const exitStart = Math.max(entranceEnd, 1 - X / D)

                const opacityKeyframes = [
                    leftAnimation.entranceOpacity,
                    1,
                    1,
                    leftAnimation.exitOpacity,
                ]
                const scaleKeyframes = [
                    leftAnimation.entranceScale,
                    1,
                    1,
                    leftAnimation.exitScale,
                ]
                const times = [0, entranceEnd, exitStart, 1]
                const easeArr = [
                    leftAnimation.appearanceEase || "linear",
                    "linear",
                    leftAnimation.exitEase || "linear",
                ]

                return (
                    <motion.div
                        key={p.id}
                        initial={{
                            x: 0,
                            top: p.y,
                            opacity: opacityKeyframes[0],
                            scale: scaleKeyframes[0],
                        }}
                        animate={{
                            x: centerX,
                            top: centerY,
                            opacity: opacityKeyframes,
                            scale: scaleKeyframes,
                        }}
                        transition={{
                            duration: D,
                            ease: leftAnimation.travelEase || "linear",
                            opacity: { duration: D, times, ease: easeArr },
                            scale: { duration: D, times, ease: easeArr },
                        }}
                        onAnimationComplete={() =>
                            setInputParticles((prev) =>
                                prev.filter((el) => el.id !== p.id)
                            )
                        }
                        style={{
                            position: "absolute",
                            left: 0,
                            transform: "translateY(-50%)",
                            zIndex: 0,
                        }}
                    >
                        {React.cloneElement(p.comp, {
                            style: { ...p.comp.props?.style },
                        })}
                    </motion.div>
                )
            })}

            {/* Core perfectly centered; pop uses duration */}
            <div
                style={{
                    position: "absolute",
                    left: "50%",
                    top: "50%",
                    transform: "translate(-50%, -50%)",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    zIndex: 3,
                }}
            >
                <motion.div
                    animate={{ scale: corePop ? coreAnimation.scale : 1 }}
                    transition={{
                        duration: Math.max(0.05, coreAnimation.duration),
                        ease: "easeInOut",
                    }}
                    style={{ transformOrigin: "center center" }}
                >
                    {hasCore ? core : <EmptyState title="Core" />}
                </motion.div>
            </div>

            {/* Right Outputs: start from core center + offset; appearance duration = core pop duration; travel ease selectable */}
            {outputParticles.map((p) => (
                <RightParticle
                    key={p.id}
                    comp={p.comp}
                    centerX={centerX}
                    centerY={centerY}
                    containerWidth={containerDimensions.width}
                    rightAnimation={rightAnimation}
                    coreDuration={p.coreDuration}
                    onDone={() =>
                        setOutputParticles((prev) =>
                            prev.filter((el) => el.id !== p.id)
                        )
                    }
                />
            ))}
        </div>
    )
}

function RightParticle({
    comp,
    centerX,
    centerY,
    containerWidth,
    rightAnimation,
    coreDuration,
    onDone,
}) {
    const ref = React.useRef(null)
    const [size, setSize] = React.useState({ w: 0, h: 0 })

    React.useLayoutEffect(() => {
        const read = () => {
            if (!ref.current) return
            const el = ref.current
            setSize({ w: el.offsetWidth || 0, h: el.offsetHeight || 0 })
        }
        read()
        const RO = window.ResizeObserver
        const ro = RO ? new RO(() => read()) : { observe() {}, disconnect() {} }
        ro.observe && ro.observe(ref.current)
        window.addEventListener("resize", read)
        return () => {
            ro.disconnect && ro.disconnect()
            window.removeEventListener("resize", read)
        }
    }, [])

    // horizontal start offset from core center (positive pushes to the right)
    const offsetX = rightAnimation.startOffsetX || 0
    const startLeft = centerX + offsetX - size.w / 2
    const startTop = centerY - size.h / 2

    const travelDuration = Math.max(0.05, rightAnimation.speed)
    const appearDuration = Math.max(0.05, coreDuration || 0.3)

    return (
        <motion.div
            initial={{
                x: 0,
                opacity: rightAnimation.initialOpacity,
                scale: rightAnimation.initialScale,
            }}
            animate={{ x: containerWidth - startLeft, opacity: 1, scale: 1 }}
            transition={{
                x: {
                    duration: travelDuration,
                    ease: rightAnimation.travelEase || "linear",
                },
                opacity: {
                    duration: appearDuration,
                    ease: rightAnimation.appearanceEase || "easeOut",
                },
                scale: {
                    duration: appearDuration,
                    ease: rightAnimation.appearanceEase || "easeOut",
                },
            }}
            onAnimationComplete={onDone}
            style={{
                position: "absolute",
                left: startLeft,
                top: startTop,
                willChange: "transform, opacity",
                zIndex: 1,
            }}
        >
            <div ref={ref} style={{ display: "inline-block" }}>
                {React.cloneElement(comp, { style: { ...comp.props?.style } })}
            </div>
        </motion.div>
    )
}

function EmptyState({ title }) {
    return (
        <div
            style={{
                padding: "12px 20px",
                borderRadius: 8,
                border: "1px dashed rgba(153, 102, 255, 0.4)",
                color: "rgba(153, 102, 255, 0.7)",
                fontSize: 12,
                background: "rgba(153, 102, 255, 0.05)",
                textAlign: "center",
                minWidth: 100,
                fontWeight: 500,
            }}
        >
            {title}
        </div>
    )
}

FlowReactor.defaultProps = {
    showDebug: false,
    leftAnimation: {
        speed: 2, // travel duration for left items
        delay: 1, // emit cadence
        initialDelay: 0,
        travelEase: "linear",
        // entrance
        entranceOpacity: 0.2,
        entranceScale: 0.6,
        entranceDuration: 0.3,
        appearanceEase: "easeOut",
        // exit (towards core)
        exitOpacity: 1,
        exitScale: 1,
        exitDuration: 0.3,
        exitEase: "easeIn",
    },
    rightAnimation: {
        speed: 2, // travel duration for right items
        delay: 1.5, // emit cadence
        initialDelay: 0,
        initialOpacity: 0.3,
        initialScale: 0.5,
        startOffsetX: 0,
        travelEase: "linear",
        appearanceEase: "easeOut",
    },
    coreAnimation: {
        duration: 0.3, // pop duration (also used for right item appearance)
        scale: 1.2,
    },
}

const easeOptions = ["linear", "easeIn", "easeOut", "easeInOut"]

addPropertyControls(FlowReactor, {
    inputs: {
        type: ControlType.Array,
        title: "Inputs",
        control: { type: ControlType.ComponentInstance },
        defaultValue: [],
    },
    core: {
        type: ControlType.ComponentInstance,
        title: "Core Instance",
        defaultValue: null,
    },
    outputs: {
        type: ControlType.Array,
        title: "Outputs",
        control: { type: ControlType.ComponentInstance },
        defaultValue: [],
    },
    leftAnimation: {
        type: ControlType.Object,
        title: "Left Animation",
        controls: {
            speed: {
                type: ControlType.Number,
                title: "Travel",
                min: 0.05,
                max: 10,
                defaultValue: 2,
            },
            delay: {
                type: ControlType.Number,
                title: "Emit Delay",
                min: 0.05,
                max: 10,
                defaultValue: 1,
            },
            initialDelay: {
                type: ControlType.Number,
                title: "Initial Delay",
                min: 0,
                max: 10,
                defaultValue: 0,
            },
            travelEase: {
                type: ControlType.Enum,
                title: "Travel Ease",
                options: easeOptions,
                optionTitles: easeOptions,
                defaultValue: "linear",
            },
            entranceOpacity: {
                type: ControlType.Number,
                title: "Enter Opacity",
                min: 0,
                max: 1,
                defaultValue: 0.2,
            },
            entranceScale: {
                type: ControlType.Number,
                title: "Enter Scale",
                min: 0.1,
                max: 2,
                defaultValue: 0.6,
            },
            entranceDuration: {
                type: ControlType.Number,
                title: "Enter Duration",
                min: 0,
                max: 10,
                defaultValue: 0.3,
            },
            appearanceEase: {
                type: ControlType.Enum,
                title: "Enter Ease",
                options: easeOptions,
                optionTitles: easeOptions,
                defaultValue: "easeOut",
            },
            exitOpacity: {
                type: ControlType.Number,
                title: "Exit Opacity",
                min: 0,
                max: 1,
                defaultValue: 1,
            },
            exitScale: {
                type: ControlType.Number,
                title: "Exit Scale",
                min: 0.1,
                max: 2,
                defaultValue: 1,
            },
            exitDuration: {
                type: ControlType.Number,
                title: "Exit Duration",
                min: 0,
                max: 10,
                defaultValue: 0.3,
            },
            exitEase: {
                type: ControlType.Enum,
                title: "Exit Ease",
                options: easeOptions,
                optionTitles: easeOptions,
                defaultValue: "easeIn",
            },
        },
    },
    rightAnimation: {
        type: ControlType.Object,
        title: "Right Animation",
        controls: {
            speed: {
                type: ControlType.Number,
                title: "Travel",
                min: 0.05,
                max: 10,
                defaultValue: 2,
            },
            delay: {
                type: ControlType.Number,
                title: "Emit Delay",
                min: 0.05,
                max: 10,
                defaultValue: 1.5,
            },
            initialDelay: {
                type: ControlType.Number,
                title: "Initial Delay",
                min: 0,
                max: 10,
                defaultValue: 0,
            },
            initialOpacity: {
                type: ControlType.Number,
                title: "Initial Opacity",
                min: 0,
                max: 1,
                defaultValue: 0.3,
            },
            initialScale: {
                type: ControlType.Number,
                title: "Initial Scale",
                min: 0.1,
                max: 2,
                defaultValue: 0.5,
            },
            startOffsetX: {
                type: ControlType.Number,
                title: "Start X Offset",
                min: -500,
                max: 500,
                defaultValue: 0,
            },
            travelEase: {
                type: ControlType.Enum,
                title: "Travel Ease",
                options: easeOptions,
                optionTitles: easeOptions,
                defaultValue: "linear",
            },
            appearanceEase: {
                type: ControlType.Enum,
                title: "Appear Ease",
                options: easeOptions,
                optionTitles: easeOptions,
                defaultValue: "easeOut",
            },
        },
    },
    coreAnimation: {
        type: ControlType.Object,
        title: "Core Animation",
        controls: {
            duration: {
                type: ControlType.Number,
                title: "Pop Duration",
                min: 0.05,
                max: 2,
                defaultValue: 0.3,
            },
            scale: {
                type: ControlType.Number,
                title: "Pop Scale",
                min: 1,
                max: 2,
                defaultValue: 1.2,
            },
        },
    },
    showDebug: {
        type: ControlType.Boolean,
        title: "Show Debug",
        defaultValue: false,
        description: "v1.0 [via SegmentUI](https://www.segmentUI.com)",
    },
})
